// Rate limiting: per-user, per-endpoint limits
const rateLimitBuckets = new Map();
const RATE_LIMITS = {
  '/api/chat/messages': { POST: 30 },      // 30 messages per minute
  '/api/feedback': { POST: 10 },            // 10 feedback submissions per minute
  '/api/knowledge/proposals': { POST: 5 },  // 5 proposals per minute
  '/api/search': { GET: 60 },               // 60 searches per minute
  '/api/review': { POST: 20 },              // 20 reviews per minute
  '/api/notepad': { POST: 30 },             // 30 notepad saves per minute
  '/api/profile': { POST: 10 },             // 10 profile updates per minute
  '/api/notifications': { POST: 30 },       // 30 notification actions per minute
  '/api/chat/read': { POST: 60 },           // 60 read receipts per minute
  '/api/chat/groups': { POST: 10 },         // 10 group operations per minute
  '/api/chat/delete': { POST: 30 },         // 30 message deletions per minute
  '/api/ollama/vision': { POST: 10 },       // 10 vision requests per minute
  '/api/admin/': { POST: 50 },              // 50 admin actions per minute (prefix match)
};

function checkRateLimit(userId, path, method) {
  const now = Date.now();
  const key = `${userId}:${path}:${method}`;
  const bucket = rateLimitBuckets.get(key);
  if (!bucket || bucket.reset <= now) {
    rateLimitBuckets.set(key, { count: 1, reset: now + RATE_LIMIT_WINDOW_MS });
    return { allowed: true, remaining: getLimit(path, method) - 1 };
  }
  const limit = getLimit(path, method);
  if (bucket.count >= limit) {
    return { allowed: false, remaining: 0, retryAfter: Math.ceil((bucket.reset - now) / 1000) };
  }
  bucket.count++;
  return { allowed: true, remaining: limit - bucket.count };
}

function getLimit(path, method) {
  // Check exact match first
  if (RATE_LIMITS[path]?.[method]) return RATE_LIMITS[path][method];
  // Check prefix match for admin endpoints
  for (const [prefix, limits] of Object.entries(RATE_LIMITS)) {
    if (path.startsWith(prefix) && limits[method]) return limits[method];
  }
  return DEFAULT_RATE_LIMIT; // Default limit
}

function tokens(query) {
  // Extract only alphanumeric Unicode characters to prevent injection
  return [...new Set((String(query).toLowerCase().match(/[\p{L}\p{N}]+/gu) || []).filter(v => v.length > 1 && v.length <= 100))];
}
function manualSearch(query, limit = 20, exact = false) {
  const parts = tokens(query); if (!parts.length) return []; const values = [];
  const clauses = parts.map(t => { values.push(`%${t}%`, `%${t}%`); return '(title LIKE ? OR content LIKE ?)' });
  return appDb.prepare(`SELECT * FROM manual_entries WHERE ${clauses.join(exact ? ' AND ' : ' OR ')} ORDER BY updated_at DESC LIMIT ?`).all(...values, limit).map(r => ({ title: `[Manual] ${r.title}`, content: r.content, document_id: `manual-${r.id}`, source_url: r.source_url, excerpt: manualExcerpt(r.content), score: -1000, images: manualEntryImages(r.id), qa_audit_result: r.qa_audit_result || '', category_preview: categoryPreview(r.content) }));
}
function kbSearch(query, limit = 20) {
  const parts = tokens(query); if (!parts.length) return [];
  // FTS5 MATCH query - escape double quotes for FTS5 syntax
  const match = parts.map(t => `"${t.replaceAll('"', '""')}"*`).join(' OR ');
  const imported = kbDb.prepare("SELECT title,content,document_id,source_url,snippet(chunks_fts,1,'','',' … ',36) excerpt,bm25(chunks_fts,4.0,1.0) score FROM chunks_fts WHERE chunks_fts MATCH ? ORDER BY score LIMIT ?").all(match, limit);
  return [...manualSearch(query, limit), ...imported.map(r => ({ ...r, category_preview: categoryPreview(r.content) }))].slice(0, limit);
}
function exactSearch(terms, limit = 20) {
  terms = [...new Set(terms.map(v => String(v || '').trim()).filter(Boolean))]; if (!terms.length) return [];
  const match = terms.map(t => `"${t.replaceAll('"', '""')}"`).join(' OR ');
  return [...terms.flatMap(t => manualSearch(t, limit, true)), ...kbDb.prepare('SELECT title,content,document_id,source_url,bm25(chunks_fts,4.0,1.0) score FROM chunks_fts WHERE chunks_fts MATCH ? ORDER BY score LIMIT ?').all(match, limit)].slice(0, limit);
}
function field(text,label) { const m=text.match(new RegExp(`(?:${label})\\s*[:：]\\s*([^\\r\\n]+)`,'iu')); return m?m[1].trim().replace(/^[\s*|.-]+|[\s*|.;-]+$/g,''):''; }
const categoryLevelLabels=['First','Second','Third','Fourth','Fifth','Sixth','Seventh','Eighth'];
function unlabeledProductId(text) {
  const lines=String(text||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean);
  const goodsIndex=lines.findIndex(line=>/^Goods\s+Name\s*:/i.test(line));
  if(goodsIndex<0)return '';
  for(let index=goodsIndex+1;index<lines.length;index++){
    const line=lines[index];
    if(/^[A-Za-z][^:]*:\s*/.test(line))break;
    if(/^[A-Za-z0-9._-]{4,100}$/.test(line))return line;
  }
  return '';
}
function structuredKnowledgeFields(content,sourceUrl='') {
  const text=String(content||'');
  const fields={product_id:field(text,'Product\\s+ID')||unlabeledProductId(text),goods_name:field(text,'Goods\\s+Name'),leaf_category:field(text,'Leaf\\s+Category'),source_url:field(text,'Source\\s+URL')||String(sourceUrl||'')};
  categoryLevelLabels.forEach((label,index)=>fields[`category_${index+1}`]=field(text,`${label}[\\s-]*level\\s+Category`));
  return fields;
}
function categoryPreview(content) {
  const fields=structuredKnowledgeFields(content);
  const parts=categoryLevelLabels.map((label,index)=>fields[`category_${index+1}`]?`${label}: ${fields[`category_${index+1}`]}`:'').filter(Boolean);
  if(fields.leaf_category)parts.push(`Leaf: ${fields.leaf_category}`);
  return parts.join(' > ').slice(0,700);
}
