    if(p==='/change-password'&&req.method==='POST'){const state=currentUser(req,res);if(!state.user){redirect(res,'/login');return;}if(!state.user.must_change_password){redirect(res,'/app');return;}const body=await readBody(req);if(!checkCsrf(req,res,state,body))return;const password=String(body.password||''),repeat=String(body.password_repeat||'');if(password.length<8){send(res,422,template('node-change-password.html').replaceAll('{{CSRF}}',state.sess.csrf).replace('{{ERROR}}','<div class="error">The new password must contain at least 8 characters.</div>'));return;}if(password!==repeat){send(res,422,template('node-change-password.html').replaceAll('{{CSRF}}',state.sess.csrf).replace('{{ERROR}}','<div class="error">Passwords do not match.</div>'));return;}appDb.prepare('UPDATE users SET password_hash=?,must_change_password=0,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(passwordHash(password),state.user.id);redirect(res,'/app');return;}
    if(p==='/logout'&&req.method==='POST'){const state=requireUser(req,res);if(!state)return;const body=await readBody(req);if(!checkCsrf(req,res,state,body))return;destroySession(res,state);redirect(res,'/login');return;}
